import React, { useCallback, useEffect, useMemo, useRef } from 'react';

export type TabKey = 'accueil' | 'apropos' | 'realisations' | 'contact';

export const TABS: ReadonlyArray<{ key: TabKey; label: string }> = [
  { key: 'accueil',      label: 'Accueil' },
  { key: 'apropos',      label: 'À propos de nous' },
  { key: 'realisations', label: 'Nos réalisations' },
  { key: 'contact',      label: 'Contactez-nous' },
] as const;

type Props = {
  active: TabKey;
  onChange: (key: TabKey) => void;
  idBase?: string; // чтобы aria-controls были уникальны, если компонент переиспользуется
};

export default function TabNav({ active, onChange, idBase = 'main-tabs' }: Props) {
  const wrapRef = useRef<HTMLDivElement>(null);
  const sliderRef = useRef<HTMLSpanElement>(null);

  const activeIndex = useMemo(
    () => Math.max(0, TABS.findIndex(t => t.key === active)),
    [active]
  );

  // Подгоняем “слайдер” под активную кнопку + реагируем на ресайз
  useEffect(() => {
    const wrap = wrapRef.current;
    const slider = sliderRef.current;
    if (!wrap || !slider) return;

    const update = () => {
      const btns = wrap.querySelectorAll<HTMLButtonElement>('[role="tab"]');
      const el = btns[activeIndex];
      if (!el) return;
      const { offsetLeft, offsetWidth } = el;
      slider.style.transform = `translateX(${offsetLeft}px)`;
      slider.style.width = `${offsetWidth}px`;
    };

    update();

    const ro = new ResizeObserver(update);
    ro.observe(wrap);
    window.addEventListener('resize', update);
    // если шрифты догружаются, тоже обновим
    document.fonts?.ready?.then(update).catch(() => {});

    return () => {
      ro.disconnect();
      window.removeEventListener('resize', update);
    };
  }, [activeIndex]);

  // Клавиатурная навигация по вкладкам (стрелки, Home/End, Enter/Space)
  const onKeyDown = useCallback(
    (e: React.KeyboardEvent) => {
      const wrap = wrapRef.current;
      if (!wrap) return;
      const tabs = Array.from(
        wrap.querySelectorAll<HTMLButtonElement>('[role="tab"]')
      );
      const current = tabs.findIndex(b => b === document.activeElement);
      if (current < 0) return;

      let next = current;
      switch (e.key) {
        case 'ArrowRight':
        case 'ArrowDown':
          next = (current + 1) % tabs.length;
          break;
        case 'ArrowLeft':
        case 'ArrowUp':
          next = (current - 1 + tabs.length) % tabs.length;
          break;
        case 'Home':
          next = 0;
          break;
        case 'End':
          next = tabs.length - 1;
          break;
        case ' ':
        case 'Enter':
          onChange(TABS[current].key);
          e.preventDefault();
          return;
        default:
          return;
      }
      tabs[next]?.focus();
      e.preventDefault();
    },
    [onChange]
  );

  return (
    <div
      className="tabs"
      role="tablist"
      aria-label="Sections du site"
      ref={wrapRef}
      onKeyDown={onKeyDown}
    >
      <span className="slider" aria-hidden="true" ref={sliderRef} />
      {TABS.map(({ key, label }, idx) => {
        const selected = active === key;
        return (
          <button
            key={key}
            type="button"
            className={`tab${selected ? ' is-active' : ''}`}
            role="tab"
            aria-selected={selected}
            aria-controls={`${idBase}-panel-${key}`}
            id={`${idBase}-tab-${key}`}
            tabIndex={selected ? 0 : -1}
            onClick={() => onChange(key)}
          >
            {label}
          </button>
        );
      })}
    </div>
  );
}
